<template>
  <div class="creative-studio">
    <header class="studio-nav">
      <button class="studio-brand" @click="router.push('/')"><span class="brand-orb">✦</span><span><b>灵感工坊</b><small>AI 创作聚合平台</small></span></button>
      <nav><button class="active">开始创作</button><button @click="scrollTo('template-zone')">灵感模板</button><button @click="scrollTo('works-zone')">我的作品</button></nav>
      <div class="studio-nav-actions"><span class="provider-pill" :class="{ ready: providerConfigured }"><i></i>{{ providerConfigured ? 'Seedance 已连接' : '等待连接模型' }}</span><el-button class="back-main-button" plain round aria-label="返回主界面" @click="router.push('/')">← 返回主界面</el-button><el-button v-if="loggedIn" text @click="openConnectionDialog">模型设置</el-button><el-button v-if="!loggedIn" round @click="login">登录后创作</el-button><el-button v-else round @click="router.push('/console')">控制台</el-button></div>
    </header>

    <main class="studio-main">
      <section class="studio-intro">
        <div><p class="studio-eyebrow">从一个念头，到一支片子</p><h1>不用写复杂提示词，<br><em>把想法说出来就好。</em></h1><p class="intro-copy">选择一个创作方式，填入你想呈现的画面；平台会把任务交给最合适的模型。第一站是 Seedance，后续模型会统一出现在这里。</p></div>
        <aside class="first-time-card"><span>01</span><div><b>第一次使用？</b><p>先选「快速成片」→ 写一句画面描述 → 用 5 秒、720p 预览。</p></div></aside>
      </section>

      <section class="creation-layout">
        <aside class="mode-rail">
          <button v-for="item in modes" :key="item.key" :class="{ active: form.mode === item.key }" @click="selectMode(item.key)"><span class="mode-icon">{{ item.icon }}</span><span><b>{{ item.title }}</b><small>{{ item.desc }}</small></span></button>
          <div class="rail-tip"><b>小提醒</b><p>使用真人照片、声音或品牌素材前，请确保你已获得相应授权。</p></div>
        </aside>

        <AutoMovieStudio v-if="form.mode === 'AUTO_MOVIE'" class="composer-card auto-movie-host" />
        <section v-else class="composer-card">
          <header class="composer-head"><div><p>{{ activeMode.kicker }}</p><h2>{{ activeMode.title }}</h2></div><button @click="showGuide = !showGuide">{{ showGuide ? '收起新手引导' : '查看新手引导' }}</button></header>
          <div v-if="showGuide" class="newbie-guide"><span>✦</span><p><b>一句好提示词：</b>主体 + 场景 + 动作 + 镜头 + 光线/风格。例：<em>一只橘猫在雨后窗台伸懒腰，镜头缓慢推近，暖色电影光。</em></p></div>
          <div class="prompt-box"><textarea v-model="form.prompt" maxlength="4000" :placeholder="activeMode.placeholder" /><div><span>{{ form.prompt.length }}/4000</span><button :disabled="!form.prompt.trim() || assisting" @click="assistPrompt">✦ {{ assisting ? '正在整理...' : '帮我写得更好' }}</button></div></div>

          <div v-if="form.mode === 'STORYBOARD'" class="storyboard-helper"><b>镜头小助手</b><span>分段写故事，模型更容易理解节奏。</span><ol><li>0–3 秒：交代人物与场景</li><li>3–7 秒：一个清晰的动作或转折</li><li>7–{{ form.duration }} 秒：有情绪的收尾画面</li></ol></div>

          <section class="reference-section">
            <div class="field-label"><label>{{ needsFirstFrame ? '首帧图片链接' : '参考素材（可选）' }}</label><small>{{ needsFirstFrame ? '图生视频需要一张首帧图' : '可用于锁定产品、角色或场景' }}</small></div>
            <el-input v-model="form.firstFrameUrl" :placeholder="needsFirstFrame ? '粘贴首帧图片的 HTTPS 链接' : '粘贴图片链接；不需要可留空'" clearable><template #prefix>▧</template></el-input>
            <p>支持 HTTPS 图片链接或已授权的 <code>asset://</code> 素材；对象存储接入后，这里会自动出现上传入口。</p>
          </section>
          <section v-if="form.mode === 'FIRST_LAST_FRAME' || form.mode === 'VIDEO_EXTEND'" class="reference-section secondary"><div class="field-label"><label>尾帧图片链接</label><small>让镜头在指定画面结束或衔接下一段。</small></div><el-input v-model="form.lastFrameUrl" placeholder="粘贴尾帧图片的 HTTPS 链接" clearable><template #prefix>▧</template></el-input></section>

          <section class="settings-grid">
            <label><span>API 来源</span><el-select v-model="connectionSelectValue" placeholder="选择模型连接" @change="handleConnectionChange"><el-option label="平台默认 Seedance" :value="0" :disabled="!platformConfigured" /><el-option v-for="connection in enabledConnections" :key="connection.id" :value="connection.id" :label="connection.displayName" /></el-select></label>
            <label><span>创作模型</span><el-select v-model="form.model" :loading="catalogLoading"><el-option v-for="model in modelOptions" :key="model.key" :value="model.key" :label="model.label"><div class="model-option"><b>{{ model.label }}</b><small>{{ model.description }}</small></div></el-option></el-select></label>
            <label><span>画面比例</span><el-select v-model="form.ratio"><el-option v-for="ratio in ratios" :key="ratio" :value="ratio" :label="ratio" /></el-select></label>
            <label><span>视频时长</span><el-select v-model="form.duration"><el-option v-for="duration in durations" :key="duration" :value="duration" :label="`${duration} 秒`" /></el-select></label>
            <label><span>清晰度</span><el-select v-model="form.resolution"><el-option label="预览 · 480p" value="480p" /><el-option label="推荐 · 720p" value="720p" /><el-option label="高清 · 1080p" value="1080p" /></el-select></label>
          </section>
          <div class="composer-bottom"><label class="audio-toggle"><input v-model="form.generateAudio" type="checkbox"><span></span>同时生成环境音与声音</label><div><small>{{ selectedSourceReady ? `任务将通过“${selectedSourceName}”提交，通常需要几十秒到几分钟。` : '请先在“模型设置”中添加自己的 URL、API Key 和模型 ID。' }}</small><el-button type="primary" size="large" :loading="submitting" @click="submitTask">✦ {{ loggedIn ? '开始生成' : '登录后开始创作' }}</el-button></div></div>
        </section>
      </section>

      <section id="template-zone" class="template-zone"><div class="section-title"><div><p class="studio-eyebrow">不知道怎么写？</p><h2>从一个灵感模板开始</h2></div><span>{{ templates.length }} 个新手友好模板</span></div><div class="template-grid"><button v-for="template in templates" :key="template.title" @click="useTemplate(template)"><span>{{ template.category }}</span><h3>{{ template.title }}</h3><p>{{ template.prompt }}</p><b>使用这个模板 →</b></button></div></section>

      <section id="works-zone" class="works-zone"><div class="section-title"><div><p class="studio-eyebrow">创作记录</p><h2>我的作品与进行中的任务</h2></div><el-button v-if="loggedIn" :loading="historyLoading" plain @click="loadTasks">刷新状态</el-button></div>
        <div v-if="!loggedIn" class="login-empty"><span>✦</span><div><b>登录后，所有创作都会保存在这里。</b><p>你可以随时回来查看任务、预览视频和继续创作。</p></div><el-button type="primary" @click="login">去登录</el-button></div>
        <div v-else-if="historyLoading && tasks.length === 0" class="works-skeleton"><i v-for="index in 3" :key="index"></i></div>
        <div v-else-if="tasks.length === 0" class="no-works"><span>⌁</span><b>还没有作品</b><p>从上面的「快速成片」开始，第一条视频会出现在这里。</p></div>
        <div v-else class="work-grid"><article v-for="task in tasks" :key="task.id" class="work-card"><div class="work-preview"><video v-if="task.videoUrl" :src="task.videoUrl" controls preload="metadata" /><img v-else-if="task.thumbnailUrl" :src="task.thumbnailUrl" alt="Generated work preview"><div v-else class="task-placeholder"><span>{{ statusGlyph(task.status) }}</span><b>{{ statusText(task.status) }}</b><small v-if="task.status === 'RUNNING'">正在把你的想法变成画面</small></div><span class="status-chip" :class="task.status.toLowerCase()">{{ statusText(task.status) }}</span></div><div class="work-card-body"><p>{{ task.projectName || modeLabel(task.mode) }}</p><h3>{{ task.prompt }}</h3><footer><span>{{ task.options?.ratio || '16:9' }} · {{ task.options?.duration || 5 }} 秒</span><a v-if="task.videoUrl" :href="task.videoUrl" target="_blank" rel="noopener">打开视频 ↗</a><button v-else-if="!isTerminal(task.status)" @click="refreshTask(task)">查询进度</button><small v-else-if="task.errorMessage">{{ task.errorMessage }}</small></footer></div></article></div>
      </section>
    </main>

    <el-dialog v-model="connectionDialogVisible" title="我的模型连接" width="min(760px, 94vw)" :teleported="false" class="connection-dialog">
      <div class="connection-help"><span>🔐</span><p><b>使用你自己的 Seedance / 方舟额度</b><br>API Key 仅发送到本站后端并加密保存，浏览器不会再次读取明文。兼容火山方舟视频生成任务协议的授权服务也可接入。<a href="https://www.volcengine.com/docs/82379/1520757?lang=zh" target="_blank" rel="noopener">查看官方接口文档 ↗</a></p></div>
      <div v-if="connections.length" class="connection-list">
        <article v-for="connection in connections" :key="connection.id" :class="{ disabled: !connection.enabled }">
          <div><b>{{ connection.displayName }}</b><span>{{ connection.provider === 'seedance' ? '视频' : connection.provider === 'openai-chat' ? '文本' : '图片' }}</span><p>{{ connection.baseUrl }}</p><small>{{ connection.models.length }} 个模型 · Key {{ connection.apiKeyPreview || '已保存' }}</small></div>
          <div class="connection-actions"><el-button size="small" :loading="testingConnectionId === connection.id" @click="testConnection(connection)">测试</el-button><el-button size="small" @click="editConnection(connection)">编辑</el-button><el-button size="small" type="danger" plain @click="deleteConnection(connection)">删除</el-button></div>
        </article>
      </div>
      <el-empty v-else description="还没有自定义模型连接" :image-size="70" />
      <el-divider>{{ connectionForm.id ? '编辑连接' : '添加新连接' }}</el-divider>
      <el-form label-position="top" class="connection-form">
        <div class="connection-form-grid">
          <el-form-item label="连接名称"><el-input v-model="connectionForm.displayName" maxlength="160" placeholder="例如：我的火山方舟" /></el-form-item>
          <el-form-item label="协议类型"><el-select v-model="connectionForm.provider" :disabled="Boolean(connectionForm.id)" @change="applyProviderPreset"><el-option label="视频 · Seedance / 方舟兼容" value="seedance" /><el-option label="文本 · OpenAI Chat 兼容" value="openai-chat" /><el-option label="图片 · OpenAI Images 兼容" value="openai-image" /></el-select></el-form-item>
        </div>
        <el-form-item label="Base URL"><el-input v-model="connectionForm.baseUrl" placeholder="https://ark.cn-beijing.volces.com" /><small class="field-tip">可填写官方域名、兼容服务根地址、以 /api/v3 结尾的地址，或完整任务接口地址。</small></el-form-item>
        <el-form-item label="API Key"><el-input v-model="connectionForm.apiKey" type="password" show-password autocomplete="new-password" :placeholder="connectionForm.id ? '留空表示保留原 Key' : '粘贴你的 API Key'" /><small v-if="connectionForm.id" class="field-tip">当前：{{ editingKeyPreview || '已配置' }}；只有填写新值时才会替换。</small></el-form-item>
        <el-form-item label="模型 ID"><el-input v-model="connectionForm.modelsText" type="textarea" :rows="4" placeholder="每行一个模型 ID，例如：&#10;doubao-seedance-1-5-pro-251215" /><small class="field-tip">可配置多个方舟 Endpoint/模型 ID，创作时会出现在模型下拉框中。</small></el-form-item>
        <div class="connection-form-grid">
          <el-form-item label="默认模型"><el-input v-model="connectionForm.defaultModel" placeholder="必须包含在上面的模型列表中" /></el-form-item>
          <el-form-item label="状态"><el-switch v-model="connectionForm.enabled" active-text="启用" inactive-text="停用" /></el-form-item>
        </div>
      </el-form>
      <template #footer><div class="dialog-footer"><el-button v-if="connectionForm.id" @click="resetConnectionForm">取消编辑</el-button><el-button type="primary" :loading="connectionSaving" @click="saveConnection">{{ connectionForm.id ? '保存修改' : '添加连接' }}</el-button></div></template>
    </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import AutoMovieStudio from '@/components/AutoMovieStudio.vue'
import http, { getHttpErrorMessage } from '@/utils/http'
import { getToken } from '@/utils/auth'

type StudioMode = 'TEXT_TO_VIDEO' | 'IMAGE_TO_VIDEO' | 'FIRST_LAST_FRAME' | 'STORYBOARD' | 'VIDEO_EXTEND' | 'AUTO_MOVIE'
type ModelOption = { key: string; label: string; description: string }
type Template = { title: string; mode: StudioMode; prompt: string; ratio: string; category: string }
type CreativeTask = { id: number; connectionId?: number; model: string; mode: StudioMode; projectName?: string; prompt: string; status: string; videoUrl?: string; thumbnailUrl?: string; errorMessage?: string; options?: { ratio?: string; duration?: number } }
type CreativeConnection = { id: number; provider: string; capability?: string; displayName: string; baseUrl: string; models: string[]; defaultModel: string; enabled: boolean; apiKeyConfigured: boolean; apiKeyPreview?: string }
const router = useRouter()
const loggedIn = ref(Boolean(getToken()))
const catalogLoading = ref(false); const historyLoading = ref(false); const submitting = ref(false); const assisting = ref(false); const showGuide = ref(true); const platformConfigured = ref(false)
const platformModelOptions = ref<ModelOption[]>([]); const platformDefaultModel = ref(''); const templates = ref<Template[]>([]); const tasks = ref<CreativeTask[]>([])
const connections = ref<CreativeConnection[]>([]); const connectionDialogVisible = ref(false); const connectionSaving = ref(false); const testingConnectionId = ref<number | null>(null); const editingKeyPreview = ref('')
const connectionForm = reactive({ id: null as number | null, provider: 'seedance', displayName: '我的火山方舟', baseUrl: 'https://ark.cn-beijing.volces.com', apiKey: '', modelsText: 'doubao-seedance-1-5-pro-251215', defaultModel: 'doubao-seedance-1-5-pro-251215', enabled: true })
let pollTimer: number | undefined
const modes: Array<{ key: StudioMode; icon: string; title: string; desc: string; kicker: string; placeholder: string }> = [
  { key: 'AUTO_MOVIE', icon: '文', title: 'TXT 自动成片', desc: '原文到完整视频', kicker: '项目式 AI 影视流水线', placeholder: '上传 TXT 或粘贴原文，逐阶段生成剧本、画像和成片…' },
  { key: 'TEXT_TO_VIDEO', icon: '✦', title: '快速成片', desc: '一句话生成视频', kicker: '最适合第一次创作', placeholder: '描述你想看到的画面：谁、在哪里、做什么、镜头怎么动…' },
  { key: 'IMAGE_TO_VIDEO', icon: '▧', title: '图片动起来', desc: '用一张图做首帧', kicker: '让静态画面有生命力', placeholder: '描述这张图接下来发生的动作，例如：人物轻轻转身，镜头缓慢推进…' },
  { key: 'FIRST_LAST_FRAME', icon: '↔', title: '首尾帧控制', desc: '指定开始和结束', kicker: '更可控的镜头过渡', placeholder: '描述从首帧过渡到尾帧的动作、镜头路径和节奏…' },
  { key: 'STORYBOARD', icon: '▤', title: '故事分镜', desc: '把小故事变成片段', kicker: '适合短故事、广告与教程', placeholder: '说说这个片段要讲的故事；可以按 [0s-3s]、[3s-7s]、[7s-10s] 描述镜头…' },
  { key: 'VIDEO_EXTEND', icon: '⌁', title: '接着拍', desc: '延续上一段镜头', kicker: '让故事自然继续', placeholder: '说明从上一段的尾帧继续发生什么，保持谁、在哪里、如何运镜…' }
]
const form = reactive({ provider: 'seedance', connectionId: null as number | null, model: '', mode: 'TEXT_TO_VIDEO' as StudioMode, prompt: '', firstFrameUrl: '', lastFrameUrl: '', ratio: '16:9', duration: 5, resolution: '720p', generateAudio: true, projectName: '' })
const connectionSelectValue = computed({
  get: () => form.connectionId ?? 0,
  set: (value: number) => { form.connectionId = value === 0 ? null : value },
})
const ratios = ['16:9', '9:16', '1:1', '4:3', '3:4', 'adaptive']; const durations = [2, 3, 5, 8, 10, 15]
const activeMode = computed(() => modes.find(item => item.key === form.mode) || modes[0])
const needsFirstFrame = computed(() => ['IMAGE_TO_VIDEO', 'FIRST_LAST_FRAME', 'VIDEO_EXTEND'].includes(form.mode))
const enabledConnections = computed(() => connections.value.filter(connection => connection.enabled && connection.provider === 'seedance'))
const selectedConnection = computed(() => connections.value.find(connection => connection.id === form.connectionId))
const providerConfigured = computed(() => platformConfigured.value || enabledConnections.value.length > 0)
const selectedSourceReady = computed(() => form.connectionId === null ? platformConfigured.value : Boolean(selectedConnection.value?.enabled))
const selectedSourceName = computed(() => selectedConnection.value?.displayName || '平台默认 Seedance')
const modelOptions = computed<ModelOption[]>(() => selectedConnection.value
  ? selectedConnection.value.models.map(model => ({ key: model, label: model, description: selectedConnection.value?.displayName || '自定义连接' }))
  : platformModelOptions.value)
onMounted(() => { void Promise.all([loadCatalog(), loadTemplates(), ...(loggedIn.value ? [loadConnections(), loadTasks()] : [])]); if (loggedIn.value) { pollTimer = window.setInterval(() => { if (tasks.value.some(task => !isTerminal(task.status))) void refreshActiveTasks() }, 8_000) } })
onBeforeUnmount(() => { if (pollTimer) window.clearInterval(pollTimer) })
async function loadCatalog() { catalogLoading.value = true; try { const { data } = await http.get('/creative/catalog'); const provider = Array.isArray(data.providers) ? data.providers.find((item: { key?: string }) => item.key === 'seedance') : undefined; platformConfigured.value = Boolean(provider?.configured); platformModelOptions.value = Array.isArray(provider?.models) ? provider.models : []; platformDefaultModel.value = String(provider?.defaultModel || platformModelOptions.value[0]?.key || ''); ensureSourceSelection() } catch (error) { ElMessage.error(getHttpErrorMessage(error, '无法读取创作模型目录')) } finally { catalogLoading.value = false } }
async function loadTemplates() { try { const { data } = await http.get('/creative/templates'); templates.value = Array.isArray(data) ? data : [] } catch { templates.value = [] } }
async function loadConnections() { if (!loggedIn.value) return; try { const { data } = await http.get('/creative/connections'); connections.value = Array.isArray(data) ? data : []; ensureSourceSelection() } catch (error) { ElMessage.error(getHttpErrorMessage(error, '无法读取模型连接')) } }
async function loadTasks() { if (!loggedIn.value) return; historyLoading.value = true; try { const { data } = await http.get('/creative/tasks'); tasks.value = Array.isArray(data) ? data : [] } catch (error) { ElMessage.error(getHttpErrorMessage(error, '无法读取作品记录')) } finally { historyLoading.value = false } }
function ensureSourceSelection() { if (form.connectionId !== null && !enabledConnections.value.some(connection => connection.id === form.connectionId)) form.connectionId = platformConfigured.value ? null : (enabledConnections.value[0]?.id ?? null); if (form.connectionId === null && !platformConfigured.value && enabledConnections.value.length) form.connectionId = enabledConnections.value[0].id; syncSelectedModel(false) }
function syncSelectedModel(force: boolean) { const options = modelOptions.value; if (force || !options.some(option => option.key === form.model)) form.model = selectedConnection.value?.defaultModel || platformDefaultModel.value || options[0]?.key || '' }
function handleConnectionChange() { syncSelectedModel(true) }
function selectMode(mode: StudioMode) { form.mode = mode }
function useTemplate(template: Template) { form.mode = template.mode; form.prompt = template.prompt; form.ratio = template.ratio; window.scrollTo({ top: 0, behavior: 'smooth' }); ElMessage.success('模板已带入，可以按你的想法继续修改') }
async function assistPrompt() { if (!loggedIn.value) return login(); assisting.value = true; try { const { data } = await http.post('/creative/prompt/assist', { prompt: form.prompt, mode: form.mode, ratio: form.ratio }); form.prompt = String(data.prompt || form.prompt); ElMessage.success('已帮你整理成更清晰的镜头描述') } catch (error) { ElMessage.error(getHttpErrorMessage(error, '提示词助手暂时不可用')) } finally { assisting.value = false } }
async function submitTask() { if (!loggedIn.value) return login(); if (!selectedSourceReady.value) { connectionDialogVisible.value = true; return ElMessage.warning('请先添加并启用一个模型连接') } if (!form.model) return ElMessage.warning('请先选择创作模型'); if (!form.prompt.trim()) return ElMessage.warning('先写下你想生成的画面吧'); if (needsFirstFrame.value && !form.firstFrameUrl.trim()) return ElMessage.warning('这个模式需要先粘贴一张首帧图片链接'); if (form.mode === 'FIRST_LAST_FRAME' && !form.lastFrameUrl.trim()) return ElMessage.warning('首尾帧模式还需要尾帧图片链接'); submitting.value = true; try { const { data } = await http.post('/creative/tasks', { ...form, referenceImageUrls: [], projectName: form.projectName || activeMode.value.title }); tasks.value = [data as CreativeTask, ...tasks.value]; ElMessage.success('任务已提交，作品区会自动更新进度'); scrollTo('works-zone') } catch (error) { ElMessage.error(getHttpErrorMessage(error, '生成任务提交失败')) } finally { submitting.value = false } }
async function refreshTask(task: CreativeTask) { try { const { data } = await http.post(`/creative/tasks/${task.id}/refresh`); replaceTask(data as CreativeTask) } catch (error) { ElMessage.error(getHttpErrorMessage(error, '暂时无法查询任务进度')) } }
async function refreshActiveTasks() { await Promise.all(tasks.value.filter(task => !isTerminal(task.status)).map(task => http.post(`/creative/tasks/${task.id}/refresh`).then(response => replaceTask(response.data as CreativeTask)).catch(() => undefined))) }
function replaceTask(next: CreativeTask) { const index = tasks.value.findIndex(task => task.id === next.id); if (index >= 0) tasks.value.splice(index, 1, next); else tasks.value.unshift(next) }
function login() { router.push({ path: '/login', query: { redirect: '/studio' } }) }
function scrollTo(id: string) { document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' }) }
function isTerminal(status: string) { return ['SUCCEEDED', 'FAILED', 'CANCELLED'].includes(status) }
function statusText(status: string) { return ({ QUEUED: '排队中', RUNNING: '生成中', SUCCEEDED: '已完成', FAILED: '未完成', CANCELLED: '已取消' } as Record<string, string>)[status] || status }
function statusGlyph(status: string) { return ({ QUEUED: '◌', RUNNING: '✦', SUCCEEDED: '✓', FAILED: '!', CANCELLED: '−' } as Record<string, string>)[status] || '◌' }
function modeLabel(mode: StudioMode) { return modes.find(item => item.key === mode)?.title || '创作任务' }
function openConnectionDialog() { resetConnectionForm(); connectionDialogVisible.value = true }
function resetConnectionForm() { connectionForm.id = null; connectionForm.provider = 'seedance'; connectionForm.displayName = '我的火山方舟'; connectionForm.baseUrl = 'https://ark.cn-beijing.volces.com'; connectionForm.apiKey = ''; connectionForm.modelsText = 'doubao-seedance-1-5-pro-251215'; connectionForm.defaultModel = 'doubao-seedance-1-5-pro-251215'; connectionForm.enabled = true; editingKeyPreview.value = '' }
function applyProviderPreset() { const presets = { seedance: ['我的火山方舟', 'https://ark.cn-beijing.volces.com', 'doubao-seedance-1-5-pro-251215'], 'openai-chat': ['我的文本模型', 'https://api.openai.com', 'gpt-4.1-mini'], 'openai-image': ['我的图片模型', 'https://api.openai.com', 'gpt-image-1'] } as const; const preset = presets[connectionForm.provider as keyof typeof presets]; connectionForm.displayName = preset[0]; connectionForm.baseUrl = preset[1]; connectionForm.modelsText = preset[2]; connectionForm.defaultModel = preset[2] }
function editConnection(connection: CreativeConnection) { connectionForm.id = connection.id; connectionForm.provider = connection.provider; connectionForm.displayName = connection.displayName; connectionForm.baseUrl = connection.baseUrl; connectionForm.apiKey = ''; connectionForm.modelsText = connection.models.join('\n'); connectionForm.defaultModel = connection.defaultModel; connectionForm.enabled = connection.enabled; editingKeyPreview.value = connection.apiKeyPreview || '****' }
function parsedConnectionModels() { return [...new Set(connectionForm.modelsText.split(/[,\r\n]+/).map(value => value.trim()).filter(Boolean))] }
async function saveConnection() { const models = parsedConnectionModels(); if (!connectionForm.displayName.trim()) return ElMessage.warning('请填写连接名称'); if (!connectionForm.baseUrl.trim()) return ElMessage.warning('请填写 Base URL'); if (!connectionForm.id && !connectionForm.apiKey.trim()) return ElMessage.warning('请填写 API Key'); if (!models.length) return ElMessage.warning('至少填写一个模型 ID'); if (!models.includes(connectionForm.defaultModel.trim())) return ElMessage.warning('默认模型必须包含在模型 ID 列表中'); connectionSaving.value = true; try { const payload = { provider: connectionForm.provider, displayName: connectionForm.displayName, baseUrl: connectionForm.baseUrl, apiKey: connectionForm.apiKey, models, defaultModel: connectionForm.defaultModel, enabled: connectionForm.enabled }; if (connectionForm.id) await http.put(`/creative/connections/${connectionForm.id}`, payload); else await http.post('/creative/connections', payload); await loadConnections(); resetConnectionForm(); ElMessage.success('模型连接已安全保存') } catch (error) { ElMessage.error(getHttpErrorMessage(error, '模型连接保存失败')) } finally { connectionSaving.value = false } }
async function testConnection(connection: CreativeConnection) { testingConnectionId.value = connection.id; try { const { data } = await http.post(`/creative/connections/${connection.id}/test`); ElMessage.success(`${data.message || '连接成功'}（${data.latencyMs ?? 0} ms）`) } catch (error) { ElMessage.error(getHttpErrorMessage(error, '连接测试失败')) } finally { testingConnectionId.value = null } }
async function deleteConnection(connection: CreativeConnection) { try { await ElMessageBox.confirm(`确定删除“${connection.displayName}”吗？`, '删除模型连接', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }); await http.delete(`/creative/connections/${connection.id}`); await loadConnections(); if (connectionForm.id === connection.id) resetConnectionForm(); ElMessage.success('模型连接已删除') } catch (error) { if (error === 'cancel' || error === 'close') return; ElMessage.error(getHttpErrorMessage(error, '模型连接删除失败')) } }
</script>

